CREATE TABLE products (id BIGINT PRIMARY KEY, title VARCHAR(255) NOT NULL, brand VARCHAR(100), category VARCHAR(80), price DECIMAL(10,2) NOT NULL, old_price DECIMAL(10,2), rating DECIMAL(2,1), stock INT DEFAULT 0, image_url TEXT, description TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id VARCHAR(64) PRIMARY KEY, customer_name VARCHAR(150), customer_phone VARCHAR(30), customer_email VARCHAR(190), city VARCHAR(80), address TEXT, subtotal DECIMAL(10,2), shipping DECIMAL(10,2), total DECIMAL(10,2), currency CHAR(3) DEFAULT 'SAR', payment_method VARCHAR(40), payment_status VARCHAR(40) DEFAULT 'pending', provider_reference VARCHAR(190), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id VARCHAR(64) NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE payment_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id VARCHAR(64), provider VARCHAR(40), event_type VARCHAR(80), provider_status VARCHAR(80), payload JSON, received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
